posts.body:
I was thinking about just something like below (copy paste to notepad, save as .js file and add as plugin). But it has the problem that the opacity affects the face too. If you don't want that (and if you want the text slide) you'd have to separate the face from the text, at least as far as I understand. Or then make it draw the elements every frame to new positions (with the changing opacity for the text).
Window_Message.prototype.updateShowFast = function() {
this._showFast = true;
};
const _myEdit1_WindowMessage_update = Window_Message.prototype.update;
Window_Message.prototype.update = function() {
_myEdit1_WindowMessage_update.call(this);
if (this._windowContentsSprite && this._windowContentsSprite.opacity < 255) {
this._windowContentsSprite.opacity += 5;
}
};
const _myEdit1_WindowMessage_newPage = Window_Message.prototype.newPage;
Window_Message.prototype.newPage = function(textState) {
_myEdit1_WindowMessage_newPage.call(this, textState);
if (this._windowContentsSprite) {
this._windowContentsSprite.opacity = 0;
}
};

@meatmanuel
Cool! But just to make sure, you are aware that the face fade in happens between every message? Like if the same dude is talking for two message boxes the fade in happens two times.
@Solar_Flare
Yeah but like I said the problem is that the face would be sliding with the text. And even if they're okay with the face fade, I doubt they want to see the face slide between messages.
And doesn't this.opacity target the whole window? Like it "removes" the whole thing. That _windowContentsSprite targets what's drawn inside.

Yeah, if you want it to be like in you example, you can modify the plugin a bit like below. But if you have large "offset" and you message box doesn't reach end of screen the text can appear outside the message box and you'd probably need some kind of masks then, not sure. But yeah I think this should work for something like in your video.
Window_Message.prototype.updateShowFast = function() {
this._showFast = true;
};
const _myEdit1_WindowMessage_update = Window_Message.prototype.update;
Window_Message.prototype.update = function() {
_myEdit1_WindowMessage_update.call(this);
if (this._windowContentsSprite) {
if (this._windowContentsSprite.opacity < 255) {
this._windowContentsSprite.opacity += 5;
}
if (this._windowContentsSprite.x > 0) {
this._windowContentsSprite.x -= 5;
if (this._windowContentsSprite.x < 0)
this._windowContentsSprite.x = 0;
}
}
};
const _myEdit1_WindowMessage_newPage = Window_Message.prototype.newPage;
Window_Message.prototype.newPage = function(textState) {
_myEdit1_WindowMessage_newPage.call(this, textState);
if (this._windowContentsSprite) {
this._windowContentsSprite.opacity = 0;
this._windowContentsSprite.x += 100;
}
};
